#include <cmath>
#include <cstdio>
#include <random>
#include <algorithm>

// Monte Carlo European call: plain vs antithetic, one seeded run (mt19937_64, seed 42).
int main() {
    const double S = 100.0, K = 105.0, r = 0.05, sigma = 0.25, T = 1.0;
    const long m = 200000;                       // pairs -> 400k paths total
    const double disc   = std::exp(-r * T);
    const double drift  = (r - 0.5 * sigma * sigma) * T;
    const double vol    = sigma * std::sqrt(T);

    std::mt19937_64 rng(42);
    std::normal_distribution<double> z(0.0, 1.0);

    double sx = 0.0, sx2 = 0.0, sp = 0.0, sp2 = 0.0;   // sums and sums of squares
    long n = 0, np = 0;
    for (long i = 0; i < m; ++i) {
        const double w   = z(rng);
        const double xu  = disc * std::max(S * std::exp(drift + vol * w) - K, 0.0);
        const double xd  = disc * std::max(S * std::exp(drift - vol * w) - K, 0.0);
        sx += xu + xd;  sx2 += xu * xu + xd * xd;  n += 2;      // plain: both legs count
        const double pair = 0.5 * (xu + xd);
        sp += pair;  sp2 += pair * pair;  ++np;                 // antithetic: pair means
    }
    auto se = [](double s, double s2, long n) {
        return std::sqrt(std::max((s2 - s * s / n) / (n - 1), 0.0) / n);
    };
    const double vPlain = se(sx, sx2, n), vAnti = se(sp, sp2, np);
    std::printf("plain      price=%.6f  se=%.6f\n", sx / n, vPlain);
    std::printf("antithetic price=%.6f  se=%.6f  VR=%.2f\n", sp / np, vAnti, (vPlain / vAnti) * (vPlain / vAnti));
    return 0;
}
